// Regenerates apple_alac_packets.inc: swift generate_apple_alac.swift > apple_alac_packets.inc
// Encodes a deterministic test signal with Apple's ALAC encoder (AVAudioConverter, exactly as
// AsyncMusic/Streaming/ALACCodec.swift does) and prints the cookie and packets as C++ hex strings.
import AVFoundation

let framesPerPacket = 4096
let sampleRate = 44100.0
let chunks = [4096, 1000]

func signal(_ total: Int) -> [Int16] {
    var s: UInt32 = 12345
    var out = [Int16](repeating: 0, count: total * 2)
    for i in 0 ..< total {
        s = s &* 1664525 &+ 1013904223
        let left = (i % 100) * 600 - 30000 + Int((s >> 24) & 0x3F) - 32
        let right = left / 2 + Int((s >> 8) & 0x0F) - 8
        out[2 * i] = Int16(left)
        out[2 * i + 1] = Int16(right)
    }
    return out
}

var description = AudioStreamBasicDescription(mSampleRate: sampleRate, mFormatID: kAudioFormatAppleLossless, mFormatFlags: kAppleLosslessFormatFlag_16BitSourceData, mBytesPerPacket: 0, mFramesPerPacket: UInt32(framesPerPacket), mBytesPerFrame: 0, mChannelsPerFrame: 2, mBitsPerChannel: 0, mReserved: 0)
let compressed = AVAudioFormat(streamDescription: &description)!
let pcm = AVAudioFormat(commonFormat: .pcmFormatInt16, sampleRate: sampleRate, channels: 2, interleaved: true)!
let converter = AVAudioConverter(from: pcm, to: compressed)!
let input = AVAudioPCMBuffer(pcmFormat: pcm, frameCapacity: AVAudioFrameCount(framesPerPacket))!
let output = AVAudioCompressedBuffer(format: compressed, packetCapacity: 2, maximumPacketSize: max(converter.maximumOutputPacketSize, 1))
let cookie = converter.magicCookie ?? Data()

func encode(_ samples: ArraySlice<Int16>, count: Int) -> Data {
    samples.withUnsafeBufferPointer { input.int16ChannelData![0].update(from: $0.baseAddress!, count: count * 2) }
    input.frameLength = AVAudioFrameCount(count)
    output.packetCount = 0
    output.byteLength = 0
    let isFull = count == framesPerPacket
    var supplied = false
    var error: NSError?
    let status = converter.convert(to: output, error: &error) { _, inputStatus in
        if supplied {
            inputStatus.pointee = isFull ? .noDataNow : .endOfStream
            return nil
        }
        supplied = true
        inputStatus.pointee = .haveData
        return input
    }
    if !isFull { converter.reset() }
    precondition(status != .error && output.packetCount >= 1)
    let d = output.packetDescriptions![0]
    return Data(bytes: output.data + Int(d.mStartOffset), count: Int(d.mDataByteSize))
}

/// Hex digits as a C++ string literal, 64 bytes per line.
func hex(_ data: Data) -> String {
    let digits = data.map { String(format: "%02x", $0) }.joined()
    return stride(from: 0, to: digits.count, by: 128).map { start -> String in
        let a = digits.index(digits.startIndex, offsetBy: start)
        let b = digits.index(a, offsetBy: min(128, digits.count - start))
        return "\n    \"" + digits[a ..< b] + "\""
    }.joined()
}

let total = chunks.reduce(0, +)
let samples = signal(total)
print("// Generated by Apple's ALAC encoder (AVAudioConverter) on macOS from alacTestSignal(); see core_tests.cpp.")
print("constexpr double kAppleALACSampleRate = \(sampleRate);")
print("constexpr const char* kAppleALACCookie =\(hex(cookie));")
var offset = 0
for (index, count) in chunks.enumerated() {
    let packet = encode(samples[(offset * 2)...], count: count)
    print("constexpr const char* kAppleALACPacket\(index) =\(hex(packet));")
    offset += count
}
print("constexpr int kAppleALACPacketFrames[] = {\(chunks.map(String.init).joined(separator: ", "))};")
